import adsk.core, adsk.fusion, adsk.cam

def run(_context):
    app = adsk.core.Application.get()

    # Get CAM manager and library manager
    cam_mgr = adsk.cam.CAMManager.get()
    lib_mgr = cam_mgr.libraryManager
    tool_libs = lib_mgr.toolLibraries

    # List all available library locations
    print('=== Tool Library Locations ===')
    for loc in [adsk.cam.LibraryLocations.LocalLibraryLocation,
                adsk.cam.LibraryLocations.CloudLibraryLocation,
                adsk.cam.LibraryLocations.ExternalLibraryLocation]:
        try:
            root_url = tool_libs.urlByLocation(loc)
            print(f'Location {loc}: {root_url.encode()}')
            # List child assets
            try:
                assets = tool_libs.childAssetURLs(root_url)
                for a in assets:
                    print(f'  Asset: {a.encode()}')
            except:
                pass
            # List child folders
            try:
                folders = tool_libs.childFolderURLs(root_url)
                for f in folders:
                    print(f'  Folder: {f.encode()}')
                    try:
                        sub_assets = tool_libs.childAssetURLs(f)
                        for sa in sub_assets:
                            print(f'    SubAsset: {sa.encode()}')
                    except:
                        pass
                    try:
                        sub_folders = tool_libs.childFolderURLs(f)
                        for sf in sub_folders:
                            print(f'    SubFolder: {sf.encode()}')
                    except:
                        pass
            except:
                pass
        except Exception as e:
            print(f'Location {loc}: ERROR - {e}')

