import adsk.core, adsk.fusion, adsk.cam

def run(_context):
    app = adsk.core.Application.get()
    cam_mgr = adsk.cam.CAMManager.get()
    lib_mgr = cam_mgr.libraryManager
    tool_libs = lib_mgr.toolLibraries

    def url_str(url):
        try: return url.toString()
        except: return str(url)

    # Access TIW library directly
    local_root = tool_libs.urlByLocation(adsk.cam.LibraryLocations.LocalLibraryLocation)

    # Find TIW asset
    assets = tool_libs.childAssetURLs(local_root)
    tiw_url = None
    for a in assets:
        astr = url_str(a)
        if 'TIW' in astr:
            tiw_url = a
            print(f'Found TIW library: {astr}')
            break

    if tiw_url is None:
        print('TIW library not found as direct asset')
        return

    # Load the library
    tiw_lib = tool_libs.toolLibraryAtURL(tiw_url)
    print(f'TIW library count: {tiw_lib.count}')

    # List tools
    for i in range(min(tiw_lib.count, 80)):
        tool = tiw_lib.item(i)
        params = tool.parameters

        # Get key params
        def get_param(name):
            try:
                p = params.itemByName(name)
                if p: return p.value.value
            except: pass
            return None

        def get_param_str(name):
            try:
                p = params.itemByName(name)
                if p: return p.value.stringValue if hasattr(p.value, 'stringValue') else str(p.value.value)
            except: pass
            return None

        dc = get_param('tool_dc')  # diameter in cm
        flen = get_param('tool_fluteLength')
        desc_p = params.itemByName('tool_description')
        desc = ''
        if desc_p:
            try: desc = desc_p.value.stringValue
            except: desc = str(desc_p.value)

        type_p = params.itemByName('tool_type')
        ttype = ''
        if type_p:
            try: ttype = type_p.value.stringValue
            except: ttype = str(type_p.value)

        if dc is not None:
            print(f'  [{i}] Type={ttype}, D={dc*10:.2f}mm, Flute={flen*10:.2f}mm if flen else "N/A", Desc={desc}')

