import adsk.core, adsk.fusion, adsk.cam

def run(_context):
    app = adsk.core.Application.get()
    cam_mgr = adsk.cam.CAMManager.get()
    lib_mgr = cam_mgr.libraryManager
    tool_libs = lib_mgr.toolLibraries

    def url_str(url):
        try: return url.toString()
        except: return str(url)

    local_root = tool_libs.urlByLocation(adsk.cam.LibraryLocations.LocalLibraryLocation)
    assets = tool_libs.childAssetURLs(local_root)
    tiw_url = None
    for a in assets:
        if 'TIW' in url_str(a):
            tiw_url = a
            break

    tiw_lib = tool_libs.toolLibraryAtURL(tiw_url)
    tool0 = tiw_lib.item(7)  # T1 - 4 flute, 44mm flute
    params = tool0.parameters

    print(f'Tool T{tiw_lib.item(7).parameters.itemByName("tool_number").value.value} - all params with "tool" in name:')
    for i in range(params.count):
        p = params.item(i)
        if 'tool' in p.name.lower() or 'diameter' in p.name.lower():
            try:
                v = p.value
                vtype = type(v).__name__
                if 'Float' in vtype:
                    print(f'  {p.name} = {v.value:.4f} (FloatParam)')
                elif 'Integer' in vtype:
                    print(f'  {p.name} = {v.value} (IntParam)')
                elif 'Choice' in vtype:
                    print(f'  {p.name} = "{v.stringValue}" (ChoiceParam)')
                elif 'String' in vtype:
                    print(f'  {p.name} = "{v.stringValue}" (StringParam)')
                elif 'Boolean' in vtype:
                    print(f'  {p.name} = {v.value} (BoolParam)')
                else:
                    print(f'  {p.name} = {vtype}')
            except Exception as e:
                print(f'  {p.name} = ERROR: {e}')

