import adsk.core, adsk.fusion, adsk.cam

def run(_context):
    app = adsk.core.Application.get()
    doc = app.activeDocument
    cam = adsk.cam.CAM.cast(doc.products.itemByProductType('CAMProductType'))
    setup = cam.setups.item(0)
    rough_op = setup.operations.item(0)
    rp = rough_op.parameters

    # Search for stepdown and stock leave params in adaptive2d
    print('Adaptive2d params with stepdown/stock/tolerance in name:')
    for i in range(rp.count):
        p = rp.item(i)
        n = p.name.lower()
        if any(kw in n for kw in ['stepdown', 'stock', 'leave', 'depth', 'axial', 'radial', 'tolerance']):
            try:
                vtype = type(p.value).__name__
                if 'Float' in vtype:
                    print(f'  {p.name}: {p.value.value:.4f}')
                elif 'Choice' in vtype:
                    print(f'  {p.name}: (choice) = {p.expression}')
                elif 'Boolean' in vtype:
                    print(f'  {p.name}: {p.value.value}')
                else:
                    print(f'  {p.name}: {vtype}')
            except Exception as e:
                print(f'  {p.name}: {e}')

